export const getCrossoverStateResponseVisitorProfileOneInterestsItemMax = 100;

export const getCrossoverStateResponseVisitorProfileOneInterestsMax = 12;

export const getCrossoverStateResponseSuperConnectsLeftMin = 0;
export const getCrossoverStateResponseSuperConnectsLeftMax = 3;

export const getCrossoverStateResponseDeckSummaryConnectionsMadeMin = 0;

export const getCrossoverStateResponseFilterOptionsItemCountMin = 0;

export const getCrossoverStateResponseFilterOptionsItemRemainingMin = 0;



export const GetCrossoverStateResponse = zod.object({
  "input_text": zod.string(),
  "remaining_builds": zod.number().int().min(getCrossoverStateResponseRemainingBuildsMin).max(getCrossoverStateResponseRemainingBuildsMax),
  "deck_id": zod.string().nullable(),
  "deck": zod.union([zod.object({
  "visitor_profile": zod.union([zod.object({
  "first_name": zod.string().max(getCrossoverStateResponseDeckOneVisitorProfileOneFirstNameMax).nullable(),
  "school": zod.string().max(getCrossoverStateResponseDeckOneVisitorProfileOneSchoolMax).nullable(),
  "major": zod.string().max(getCrossoverStateResponseDeckOneVisitorProfileOneMajorMax).nullable(),
  "year": zod.string().max(getCrossoverStateResponseDeckOneVisitorProfileOneYearMax).nullable(),
  "career_goals": zod.string().max(getCrossoverStateResponseDeckOneVisitorProfileOneCareerGoalsMax),
  "interests": zod.array(zod.string().max(getCrossoverStateResponseDeckOneVisitorProfileOneInterestsItemMax)).max(getCrossoverStateResponseDeckOneVisitorProfileOneInterestsMax)
}),zod.null()]),
  "matches": zod.array(zod.object({
  "profile_id": zod.number().int().min(1),
  "match_score": zod.number().int().min(getCrossoverStateResponseDeckOneMatchesItemMatchScoreMin).max(getCrossoverStateResponseDeckOneMatchesItemMatchScoreMax),
  "why_connect": zod.string().min(getCrossoverStateResponseDeckOneMatchesItemWhyConnectMin).max(getCrossoverStateResponseDeckOneMatchesItemWhyConnectMax),
  "icebreaker": zod.string().min(1).max(getCrossoverStateResponseDeckOneMatchesItemIcebreakerMax)
})).max(getCrossoverStateResponseDeckOneMatchesMax),
  "career_tip": zod.union([zod.object({
  "field": zod.string().min(1).max(getCrossoverStateResponseDeckOneCareerTipOneFieldMax),
  "reason": zod.string().min(1).max(getCrossoverStateResponseDeckOneCareerTipOneReasonMax),
  "profile_id": zod.number().int().min(1)
}),zod.null()]),
  "insufficient_input": zod.boolean(),
  "reason": zod.string().max(getCrossoverStateResponseDeckOneReasonMax).nullable()
}),zod.null()]),
  "visitor_profile": zod.union([zod.object({
  "first_name": zod.string().max(getCrossoverStateResponseVisitorProfileOneFirstNameMax).nullable(),
  "school": zod.string().max(getCrossoverStateResponseVisitorProfileOneSchoolMax).nullable(),
  "major": zod.string().max(getCrossoverStateResponseVisitorProfileOneMajorMax).nullable(),
  "year": zod.string().max(getCrossoverStateResponseVisitorProfileOneYearMax).nullable(),
  "career_goals": zod.string().max(getCrossoverStateResponseVisitorProfileOneCareerGoalsMax),
  "interests": zod.array(zod.string().max(getCrossoverStateResponseVisitorProfileOneInterestsItemMax)).max(getCrossoverStateResponseVisitorProfileOneInterestsMax)
}),zod.null()]),
  "profile_confirmed": zod.boolean(),
  "deck_order": zod.array(zod.number().int()),
  "swipes": zod.array(zod.object({
  "id": zod.number().int(),
  "profile_id": zod.number().int(),
  "direction": zod.enum(['left', 'right', 'super']),
  "created_at": zod.string()
})),
  "super_connects_left": zod.number().int().min(getCrossoverStateResponseSuperConnectsLeftMin).max(getCrossoverStateResponseSuperConnectsLeftMax),
  "deck_summary": zod.object({
  "connections_made": zod.number().int().min(getCrossoverStateResponseDeckSummaryConnectionsMadeMin),
  "top_shared_interest": zod.string().nullable()
}),
  "deck_filter": zod.enum(['all', 'other_schools', 'other_majors', 'shared_interests', 'similar_goals']),
  "visible_order": zod.array(zod.number().int()).describe('deck_order narrowed by deck_filter, same relative order'),
  "filter_options": zod.array(zod.object({
  "id": zod.enum(['all', 'other_schools', 'other_majors', 'shared_interests', 'similar_goals']),
  "available": zod.boolean().describe('False when the visitor profile lacks the fact this filter compares'),
  "count": zod.number().int().min(getCrossoverStateResponseFilterOptionsItemCountMin).describe('Cards in this deck that match'),
  "remaining": zod.number().int().min(getCrossoverStateResponseFilterOptionsItemRemainingMin).describe('Matching cards not yet swiped')
}))
})


/**
 * @summary Public redacted usage history
 */
export const GetCrossoverHistoryResponse = zod.object({
  "records": zod.array(zod.object({
  "id": zod.number().int(),
  "input_text": zod.string(),
  "status": zod.enum(['success', 'error', 'rate_limited', 'invalid_input']),
  "is_sample": zod.boolean(),
  "is_yours": zod.boolean(),
  "created_at": zod.string(),
  "top_matches": zod.array(zod.string()),
  "career_tip": zod.string(),
  "output_json": zod.string().describe('Redacted JSON text for expandable details')
})),
  "total": zod.number().int(),
  "sample_count": zod.number().int(),
  "profile_count": zod.number().int(),
  "school_count": zod.number().int()
})


/**
 * @summary Fictional sample people
 */
export const GetCrossoverProfilesResponseItem = zod.object({
  "id": zod.number().int(),
  "first_name": zod.string(),
  "school": zod.string(),
  "major": zod.string(),
  "year": zod.string(),
  "headline": zod.string(),
  "career_goals": zod.string(),
  "interests": zod.array(zod.string()),
  "ask_me_about": zod.string(),
  "is_sample": zod.boolean()
})
export const GetCrossoverProfilesResponse = zod.array(GetCrossoverProfilesResponseItem)


/**
 * Returns server health status
 * @summary Health check
 */
export const HealthCheckResponse = zod.object({
  "status": zod.string()
})


